ALTER TABLE live_sessions ADD COLUMN app_id text, ADD COLUMN room_id text, ADD COLUMN room_binding_id text, ADD COLUMN installation_id text, ADD COLUMN live_profile text, ADD COLUMN authorization_id text, ADD COLUMN candidate_digest text, ADD COLUMN grant_digest text, ADD COLUMN authorization_boot_id text, ADD COLUMN session_mono_start_ns bigint, ADD COLUMN authorization_elapsed_ms bigint;
CREATE UNIQUE INDEX uq_active_official_session ON live_sessions(app_id,room_id) WHERE mode='official' AND status IN ('ACTIVE','ENDING','RECOVERY_REQUIRED');
ALTER TABLE score_jobs ADD COLUMN claim_token text, ADD COLUMN claim_boot text, ADD COLUMN attempt bigint NOT NULL DEFAULT 0, ADD COLUMN input_versions jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE next_selections ADD COLUMN manifest_id text, ADD COLUMN calibration_id text, ADD COLUMN next_rules_version bigint NOT NULL DEFAULT 1, ADD COLUMN invalidated_at timestamptz;
CREATE TABLE operation_audits (id text PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now(),actor_id text NOT NULL,action text NOT NULL,resource_id text,resource_version bigint NOT NULL DEFAULT 0,request_id text,reason text,details jsonb NOT NULL DEFAULT '{}'::jsonb);
ALTER TABLE guesses ADD COLUMN provider_test boolean, ADD COLUMN admitted_relay_ms bigint;
ALTER TABLE business_commands ADD COLUMN resource_id text;
ALTER TABLE score_jobs ADD COLUMN cached_score double precision, ADD COLUMN score_completed_ns bigint;
CREATE INDEX ix_score_jobs_work ON score_jobs(status,lease_until,created_at) WHERE status IN ('queued','running','waiting');
ALTER TABLE wordbank_catalog ADD COLUMN model_manifest_id text, ADD COLUMN model_manifest_sha256 text;
ALTER TABLE rounds ADD COLUMN next_start_at timestamptz;
ALTER TABLE wordbank_catalog ADD COLUMN joint_identity jsonb NOT NULL DEFAULT '{}'::jsonb, ADD COLUMN bundle_digest text;
CREATE TABLE model_manifests (id text PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now(),model_manifest_id text NOT NULL,manifest_sha256 text NOT NULL UNIQUE,manifest jsonb NOT NULL DEFAULT '{}'::jsonb,UNIQUE(model_manifest_id,manifest_sha256));
CREATE TABLE calibrations (id text PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now(),puzzle_version_id text NOT NULL REFERENCES puzzle_versions(id),evaluation_id text NOT NULL,manifest_sha256 text NOT NULL,artifact_sha256 text NOT NULL,artifact jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE bundle_activations (id text PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now(),actor_id text NOT NULL,identity_sha256 text NOT NULL,result jsonb NOT NULL DEFAULT '{}'::jsonb);
ALTER TABLE guess_rejections ADD COLUMN source_mode text NOT NULL DEFAULT 'manual', ADD COLUMN provider_test boolean;
ALTER TABLE guess_rejections DROP CONSTRAINT IF EXISTS guess_rejections_session_id_source_id_key;
ALTER TABLE guess_rejections ADD CONSTRAINT uq_rejected_source UNIQUE(session_id,source_mode,source_id);
CREATE INDEX ix_guess_rate_mono ON guesses(session_id,participant_id,boot_id,admitted_mono_ns);
CREATE INDEX ix_guess_rate_virtual ON guesses(session_id,participant_id,admitted_virtual_ms);
CREATE INDEX ix_guess_rate_relay ON guesses(session_id,participant_id,admitted_relay_ms);
CREATE TABLE bundle_imports (id text PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now(),actor_id text NOT NULL,file_sha256 text NOT NULL,identity_sha256 text NOT NULL,result jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE resource_origins (id text PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now(),command_id text NOT NULL,puzzle_version_id text NOT NULL,evaluation_id text NOT NULL,file_sha256 text NOT NULL,imported_by text NOT NULL,UNIQUE(command_id,puzzle_version_id));
